*{box-sizing:border-box}body{margin:0;background:#dce9f0;color:#173a50;font:15px/1.7 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:32px 20px}h1{font-size:28px;margin:4px 0 12px}.eyebrow{font-size:12px;letter-spacing:.16em}header p,small{color:#526773}.panel{background:#fff;border:1px solid #9bafb4;padding:20px;margin:18px 0;border-radius:6px}.bar{display:flex;flex-wrap:wrap;align-items:center;gap:12px}button,input,select{font:inherit}button{background:#173a50;color:white;border:1px solid #173a50;padding:7px 14px;border-radius:4px;cursor:pointer}button:hover{background:#245c78}button:disabled{opacity:.45;cursor:default}input[type=number],input[type=text],select{max-width:100%;padding:6px;border:1px solid #9bafb4;border-radius:3px}input[type=number]{width:95px}label{display:inline-flex;align-items:center;gap:6px}#drop{border:2px dashed #9bafb4;padding:24px;text-align:center;background:#fff}#drop.over{border-color:#173a50;background:#eaf2f7}canvas{display:block;max-width:100%;max-height:65vh;margin:12px auto;touch-action:none;border:1px solid #90a4ad;background:repeating-conic-gradient(#eee 0 25%,#fff 0 50%) 0/20px 20px}#canvas.crop{cursor:crosshair}#canvas{cursor:default}#list{list-style:none;padding:0}#list li{display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid #ddd}#list li.excluded{color:#777;background:#eee}#list input{min-width:80px;flex:1}#list img{width:48px;height:48px;object-fit:contain}#list .order{display:flex;gap:4px}#list button{padding:4px 8px}#status{position:sticky;bottom:8px;background:#173a50;color:white;border-radius:4px;padding:8px 12px;min-height:42px;z-index:2}footer{border-top:1px solid #9bafb4;margin-top:28px;padding-top:12px}details{margin:12px 0}summary{cursor:pointer}#info{white-space:pre-line}.hint{font-size:13px;color:#526773}@media(max-width:600px){main{padding:20px 12px}.panel{padding:12px}#list li{flex-wrap:wrap}#list .order{margin-left:auto}}
